func TestAPIChatChannelLeavesCleanly(t *testing.T) {
	requireChannelTests(t)
	ctx := context.Background()
	withHarnessSocket(t, func(h *harnessClient, socket *platform.Socket) {
		h.registerScenario(t, map[string]any{
			"topic":  "api:chat:team:test-id:thread:test-id",
			"onJoin": []any{map[string]any{"type": "autoReply"}},
		})
		channel, err := platform.JoinAPIChatChannelTeamThread(ctx, socket, "test-id", "test-id", platform.Ptr("test-value"), platform.Ptr("test-value"), platform.Ptr(true), platform.Ptr(1))
		if err != nil {
			t.Fatalf("join failed: %v", err)
		}
		if err := channel.Leave(ctx); err != nil {
			t.Fatalf("leave failed: %v", err)
		}
	})
}
